"""CLI body for `harness activity backfill`."""

from __future__ import annotations

from pathlib import Path

from rich.console import Console

from harness.site.activity_backfill import backfill_activity

_out = Console()
_err = Console(stderr=True)


def cmd_activity_backfill(
    *,
    root: str = ".",
    sessions_dir: str | None = None,
    dry_run: bool = False,
) -> int:
    """Rebuild docs/activity/*.jsonl from the local Claude Code session store."""
    root_path = Path(root).resolve()
    if not root_path.is_dir():
        _err.print(f"[red]root not found: {root_path}[/red]")
        return 1
    sessions_root = Path(sessions_dir).expanduser() if sessions_dir else None

    result = backfill_activity(root_path, sessions_root=sessions_root, dry_run=dry_run)

    if result.sessions_scanned == 0:
        _err.print(
            "[yellow]no session transcripts found for this project under "
            f"{(sessions_root or Path.home() / '.claude' / 'projects')}[/yellow]\n"
            "Activity can only be rebuilt on the machine that ran the sessions."
        )

    verb = "would write" if dry_run else "wrote"
    _out.print(
        f"sessions scanned : {result.sessions_scanned}\n"
        f"invocations       : {result.invocations}\n"
        f"rows before       : {result.rows_before}\n"
        f"rows after        : {result.rows_after}  "
        f"(preserved {result.preserved_other_sessions} from other sessions)\n"
        f"{verb} months     : {', '.join(result.months_written) or '—'}"
    )
    if dry_run:
        _out.print("[cyan]dry-run — no files changed[/cyan]")
    return 0
